// Card 42d9d64c — final analysis pass over the full 20-run corpus. Read-only: reads runs.ndjson and
// measured-timings.ndjson (both already committed alongside this script) and prints the cross-tabs the
// README is built from, so every number in the README can be regenerated by re-running this file.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const DIR = path.join(HERE, "..");
const runs = fs.readFileSync(path.join(DIR, "runs.ndjson"), "utf8").trim().split("\n").map(JSON.parse.bind(JSON));
const measured = fs.readFileSync(path.join(DIR, "measured-timings.ndjson"), "utf8").trim().split("\n").map(JSON.parse.bind(JSON));

const passRuns = runs.filter((r) => r.outcome === "pass");
const failRuns = runs.filter((r) => r.outcome === "fail");

console.log(`\n=== POPULATION ===`);
console.log(`total runs: ${runs.length} (${passRuns.length} pass, ${failRuns.length} fail)`);

console.log(`\n=== THE QUESTION: absent-on-onExit signal, pass vs fail ===`);
const passAbsentCounts = passRuns.map((r) => r.absentCount);
console.log(`pass rows absentCount values: ${JSON.stringify(passAbsentCounts)} (all zero? ${passAbsentCounts.every((c) => c === 0)})`);
for (const r of failRuns) {
  console.log(`  FAIL run ${r.run}: failedLabel=${r.failedLabel} failedIndex=${r.failedSessionIndex} strandedExpected=${JSON.stringify(r.strandedExpected)} absentSessions=${JSON.stringify(r.absentSessions)} strandedSetMatchesAbsent=${r.strandedSetMatchesAbsent} anyAbsentNotStrandedOrFailed=${r.anyAbsentNotStrandedOrFailed} failedSessionAlsoAbsent=${r.failedSessionAlsoAbsent}`);
}
console.log(`ALL fail rows strandedSetMatchesAbsent: ${failRuns.every((r) => r.strandedSetMatchesAbsent)}`);
console.log(`ANY fail row anyAbsentNotStrandedOrFailed (falsifier): ${failRuns.some((r) => r.anyAbsentNotStrandedOrFailed)}`);

console.log(`\n=== give-up recovery vs outcome ===`);
for (const r of runs) {
  console.log(`  run ${r.run} outcome=${r.outcome} giveUpRecoveryCount=${r.giveUpRecoveryCount}`);
}
const passGiveUps = passRuns.map((r) => r.giveUpRecoveryCount);
const failGiveUps = failRuns.map((r) => r.giveUpRecoveryCount);
console.log(`pass giveUpRecoveryCount: ${JSON.stringify(passGiveUps)} (sum=${passGiveUps.reduce((a,b)=>a+b,0)}, runs with >=1: ${passGiveUps.filter(c=>c>0).length}/${passGiveUps.length})`);
console.log(`fail giveUpRecoveryCount: ${JSON.stringify(failGiveUps)} (sum=${failGiveUps.reduce((a,b)=>a+b,0)}, runs with >=1: ${failGiveUps.filter(c=>c>0).length}/${failGiveUps.length})`);

console.log(`\n=== stallAssertionMs (fail-arm only) ===`);
const stallVals = failRuns.map((r) => r.stallAssertionMs).filter((v) => v != null);
console.log(`values: ${JSON.stringify(stallVals)}`);
console.log(`min=${Math.min(...stallVals)} max=${Math.max(...stallVals)} mean=${Math.round(stallVals.reduce((a,b)=>a+b,0)/stallVals.length)}`);

const stats = (arr) => arr.length ? { n: arr.length, min: Math.min(...arr), max: Math.max(...arr), mean: Math.round(arr.reduce((a,b)=>a+b,0)/arr.length) } : { n: 0 };

console.log(`\n=== measured SessionStart->FIXTURE_RECEIVED, per-fixture pass vs fail (UNSPLIT — includes the failure's own elevated reading) ===`);
const byFixture = {};
for (const m of measured) {
  byFixture[m.fixture] ??= { pass: [], fail: [] };
  byFixture[m.fixture][m.outcome].push(m.sessionStartToReceivedMs);
}
for (const [fixture, { pass, fail }] of Object.entries(byFixture)) {
  console.log(`  ${fixture}: PASS ${JSON.stringify(stats(pass))}  |  FAIL-run ${JSON.stringify(stats(fail))}`);
}

console.log(`\n=== SAME, but SPLIT: the failing sub-fixture's own reading vs the OTHER (genuinely non-failing) sub-fixtures within failing runs ===`);
const failSiteKey = new Set(failRuns.map((r) => `${r.run}|${r.failedLabel}`));
const byFixtureSplit = {};
for (const m of measured) {
  if (m.outcome !== "fail") continue;
  byFixtureSplit[m.fixture] ??= { ownFailure: [], nonFailing: [] };
  const isFailureSite = failSiteKey.has(`${m.run}|${m.fixture}`);
  byFixtureSplit[m.fixture][isFailureSite ? "ownFailure" : "nonFailing"].push(m.sessionStartToReceivedMs);
}
for (const [fixture, { ownFailure, nonFailing }] of Object.entries(byFixtureSplit)) {
  const passStats = stats(byFixture[fixture]?.pass ?? []);
  console.log(`  ${fixture}: PASS ${JSON.stringify(passStats)}  |  non-failing-within-a-fail-run ${JSON.stringify(stats(nonFailing))}  |  the-failure-itself ${JSON.stringify(stats(ownFailure))}`);
}

console.log(`\n=== per-run: every OTHER (non-failing) sub-fixture's value vs its own pass-population mean, for each fail run ===`);
for (const r of failRuns) {
  const rowsForRun = measured.filter((m) => m.run === r.run && m.fixture !== r.failedLabel);
  const deltas = rowsForRun.map((m) => {
    const passMean = stats(byFixture[m.fixture]?.pass ?? []).mean;
    return { fixture: m.fixture, value: m.sessionStartToReceivedMs, passMean, deltaVsPassMean: m.sessionStartToReceivedMs - passMean };
  });
  console.log(`  run ${r.run} (failed at ${r.failedLabel}): ${JSON.stringify(deltas)}`);
}

console.log(`\n=== duration (ms) pass vs fail ===`);
console.log(`pass durationMs: ${JSON.stringify(passRuns.map(r=>r.durationMs))}`);
console.log(`fail durationMs: ${JSON.stringify(failRuns.map(r=>r.durationMs))}`);

console.log(`\n=== maxInterEventGapPreFailureMs (retired proxy) sanity: any pass row exceeding stall budget 15000? ===`);
for (const r of passRuns) {
  if (r.maxInterEventGapPreFailureMs > 15000) console.log(`  run ${r.run}: maxInterEventGapPreFailureMs=${r.maxInterEventGapPreFailureMs} (PASSED anyway — proxy falsified)`);
}
